/**
 * Experiment 3 - round trip SQL -> model -> SQL.
 *
 * Inputs: DDL generated by the tool for every corpus model and dialect, plus 8 hand-written
 * dialect-neutral DDL files (evaluation/roundtrip/*.sql, written before any output was seen).
 * Each input is executed on the real engine, parsed by the reverse-engineering importer, converted to the
 * canonical IR, exported again for the same dialect, executed again and the two catalogs are compared.
 */
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { manifest, loadModel, toIR, generate, ROOT } from '../lib/pipeline.mjs';
import { parseSQLToModel } from '../../src/import/sqlParser.js';
import { openDialect, runStatements, DIALECTS } from '../lib/db.mjs';
import { writeTable, writeLog } from '../lib/report.mjs';

const HAND_DIR = join(ROOT, 'evaluation', 'roundtrip');

const family = (column) => {
  const type = `${column.type} ${column.columnType}`.toLowerCase();
  if (/tinyint\(1\)|bool/.test(type)) return 'bool';
  if (/uuid/.test(type)) return 'uuid';
  if (/int|serial/.test(type)) return 'int';
  if (/decimal|numeric|real|float|double/.test(type)) return 'num';
  if (/timestamp|datetime/.test(type)) return 'timestamp';
  if (/date/.test(type)) return 'date';
  return 'text';
};
const list = (items) => items.map((x) => x.toLowerCase()).join(',');

/** Normalised view of a catalog: everything the comparison looks at, keyed by lower-case names. */
function view(catalog) {
  const tables = {};
  for (const [name, t] of Object.entries(catalog.tables)) {
    tables[name.toLowerCase()] = {
      columns: Object.fromEntries(t.columns.map((c) => [c.name.toLowerCase(), { family: family(c), nullable: c.nullable }])),
      pk: t.pk.map((c) => c.toLowerCase()),
      fks: t.fks.map((f) => `${list(f.cols)}->${f.ref.toLowerCase()}(${list(f.refCols)})`).sort(),
      uniques: t.uniques.map((u) => list(u.cols ?? u)).sort(),
    };
  }
  return tables;
}

/** Differences between two views, as { construct, detail } entries. */
export function diffViews(before, after) {
  const out = [];
  for (const name of Object.keys(before)) {
    if (!after[name]) {
      out.push({ construct: 'table', detail: `table ${name} not regenerated` });
      continue;
    }
    const a = before[name];
    const b = after[name];
    for (const col of Object.keys(a.columns)) {
      if (!b.columns[col]) out.push({ construct: 'column', detail: `${name}.${col} lost` });
      else {
        if (a.columns[col].family !== b.columns[col].family) out.push({ construct: 'column type', detail: `${name}.${col}: ${a.columns[col].family} -> ${b.columns[col].family}` });
        if (a.columns[col].nullable !== b.columns[col].nullable) out.push({ construct: 'nullability', detail: `${name}.${col}: nullable ${a.columns[col].nullable} -> ${b.columns[col].nullable}` });
      }
    }
    for (const col of Object.keys(b.columns)) if (!a.columns[col]) out.push({ construct: 'extra column', detail: `${name}.${col} added` });
    if (list(a.pk) !== list(b.pk)) out.push({ construct: a.pk.length > 1 || b.pk.length > 1 ? 'composite primary key' : 'primary key', detail: `${name}: (${a.pk}) -> (${b.pk})` });
    for (const fk of a.fks) if (!b.fks.includes(fk)) out.push({ construct: fk.includes(',') ? 'composite foreign key' : 'foreign key', detail: `${name}: ${fk} lost or changed` });
    for (const fk of b.fks) if (!a.fks.includes(fk)) out.push({ construct: 'extra foreign key', detail: `${name}: ${fk} added` });
    for (const u of a.uniques) if (!b.uniques.includes(u)) out.push({ construct: u.includes(',') ? 'composite unique' : 'unique', detail: `${name}: UNIQUE(${u}) lost` });
    // A UNIQUE over exactly the primary key is implied by it: still a catalog difference, but not a semantic one.
    for (const u of b.uniques) if (!a.uniques.includes(u)) out.push({ construct: u === list(b.pk) ? 'redundant unique on primary key (no semantic change)' : 'extra unique', detail: `${name}: UNIQUE(${u}) added` });
  }
  for (const name of Object.keys(after)) if (!before[name]) out.push({ construct: 'extra table', detail: `table ${name} added` });
  return out;
}

const unique = () => 'unique';
/** Conceptual constructs of a flat model (corpus model or model recovered by the importer). */
function conceptualFeatures(model) {
  const weakIds = new Set(model.relationships.flatMap((r) => r.connections.filter((c) => c.weak).map((c) => c.entityId)));
  const card = (c) => { const [min, max] = String(c.cardinality || '').split(','); return { min: Number(min), max }; };
  const children = new Set(model.attributes.filter((a) => a.parentType === 'attribute').map((a) => a.parentId));
  const rels = model.relationships;
  return {
    'strong entity': model.entities.filter((e) => !weakIds.has(e.id)).length,
    'weak entity (dependent connection)': weakIds.size,
    'binary N:M relationship': rels.filter((r) => r.connections.length === 2 && r.connections.every((c) => ['N', 'n'].includes(String(card(c).max)))).length,
    'ternary or higher relationship': rels.filter((r) => r.connections.length >= 3).length,
    'recursive relationship': rels.filter((r) => new Set(r.connections.map((c) => c.entityId)).size < r.connections.length).length,
    'relationship with its own attributes': rels.filter((r) => model.attributes.some((a) => a.parentType === 'relationship' && a.parentId === r.id)).length,
    'named role on a connection': rels.reduce((n, r) => n + r.connections.filter((c) => c.role).length, 0),
    'total participation (min >= 1)': rels.reduce((n, r) => n + r.connections.filter((c) => card(c).min >= 1).length, 0),
    'arbitrary bound (max > 1 and not N)': rels.reduce((n, r) => n + r.connections.filter((c) => Number(card(c).max) > 1).length, 0),
    'composite attribute': children.size,
    'multivalued attribute': model.attributes.filter((a) => a.multivalued).length,
    'derived attribute': model.attributes.filter((a) => a.derived).length,
    'specialization (T/P, D/C)': (model.specializations || []).filter((s) => s.genType !== 'U').length,
    'category (U)': (model.specializations || []).filter((s) => s.genType === 'U').length,
    aggregation: (model.aggregations || []).length,
    'post-it note': (model.postits || []).length,
  };
}

const COUNTS = {
  'CHECK constraint': /\bCHECK\s*\(/gi,
  'DEFAULT value': /\bDEFAULT\b/gi,
  'secondary index': /\bCREATE\s+(?:UNIQUE\s+)?INDEX\b/gi,
  'ON DELETE RESTRICT/SET NULL/NO ACTION': /ON\s+DELETE\s+(?:RESTRICT|SET\s+NULL|NO\s+ACTION)/gi,
  'ON DELETE CASCADE': /ON\s+DELETE\s+CASCADE/gi,
};
const count = (text, pattern) => (text.match(pattern) || []).length;

export async function runRoundTripExperiment({ config, log }) {
  const inputs = [];
  for (const dialect of DIALECTS) {
    for (const m of manifest.models) inputs.push({ source: 'generated', id: m.id, dialect, ddl: generate(toIR(loadModel(m.file)), dialect) });
    for (const file of readdirSync(HAND_DIR).filter((f) => f.endsWith('.sql')).sort()) {
      inputs.push({ source: 'hand-written', id: file.replace(/\.sql$/, ''), dialect, ddl: readFileSync(join(HAND_DIR, file), 'utf8') });
    }
  }
  const rows = [];
  const diffs = [];
  const featureTotals = {};
  const inventory = { table: 0, column: 0, 'column type': 0, nullability: 0, 'primary key': 0, 'composite primary key': 0, 'foreign key': 0, 'composite foreign key': 0, unique: 0, 'composite unique': 0 };
  const adapters = {};
  for (const dialect of DIALECTS) adapters[dialect] = await openDialect(dialect, config);
  for (const input of inputs) {
    const adapter = adapters[input.dialect];
    const row = { source: input.source, input: input.id, dialect: input.dialect, original_ddl: '', parse: '', regenerated_ddl: '', differences: '', verdict: '' };
    const db1 = await adapter.fresh();
    let db2;
    try {
      const run1 = await runStatements(db1, input.ddl);
      row.original_ddl = run1.errors.length ? `error: ${run1.errors[0].message}` : 'ok';
      if (run1.errors.length) { row.verdict = 'input DDL rejected by the engine'; rows.push(row); continue; }
      const before = view(await db1.introspect());
      for (const t of Object.values(before)) {
        inventory.table++;
        const n = Object.keys(t.columns).length;
        inventory.column += n;
        inventory['column type'] += n;
        inventory.nullability += n;
        inventory[t.pk.length > 1 ? 'composite primary key' : 'primary key'] += t.pk.length ? 1 : 0;
        for (const fk of t.fks) inventory[fk.split('->')[0].includes(',') ? 'composite foreign key' : 'foreign key']++;
        for (const u of t.uniques) if (u !== list(t.pk)) inventory[u.includes(',') ? 'composite unique' : unique()]++;
      }
      let regenerated;
      try {
        regenerated = generate(toIR(parseSQLToModel(input.ddl)), input.dialect);
        row.parse = 'ok';
      } catch (error) {
        row.parse = `error: ${String(error.message).split('\n')[0]}`;
        row.verdict = 'reverse engineering failed';
        rows.push(row);
        continue;
      }
      db2 = await adapter.fresh();
      const run2 = await runStatements(db2, regenerated);
      row.regenerated_ddl = run2.errors.length ? `error: ${run2.errors[0].message}` : 'ok';
      if (run2.errors.length) { row.verdict = 'regenerated DDL rejected by the engine'; rows.push(row); continue; }
      const found = diffViews(before, view(await db2.introspect()));
      row.differences = found.length;
      row.verdict = found.length ? 'differs' : 'identical';
      for (const d of found) diffs.push({ ...input, ...d });
      // Features the catalog view does not cover: count them textually in input and output.
      for (const [name, pattern] of Object.entries(COUNTS)) {
        featureTotals[name] ||= { input: 0, output: 0 };
        featureTotals[name].input += count(input.ddl, pattern);
        featureTotals[name].output += count(regenerated, pattern);
      }
    } finally {
      await db1.close();
      if (db2) await db2.close();
    }
    rows.push(row);
  }
  for (const dialect of DIALECTS) await adapters[dialect].closeAll();

  writeTable('roundtrip_cases', rows, [
    { key: 'source', header: 'Source' },
    { key: 'input', header: 'Input' },
    { key: 'dialect', header: 'Dialect' },
    { key: 'original_ddl', header: 'Original DDL' },
    { key: 'parse', header: 'Reverse engineering' },
    { key: 'regenerated_ddl', header: 'Regenerated DDL' },
    { key: 'differences', header: 'Differences', align: 'r' },
    { key: 'verdict', header: 'Verdict' },
  ]);
  const summary = ['generated', 'hand-written'].flatMap((source) =>
    DIALECTS.map((dialect) => {
      const own = rows.filter((r) => r.source === source && r.dialect === dialect);
      return {
        source,
        dialect,
        cases: own.length,
        identical: own.filter((r) => r.verdict === 'identical').length,
        differs: own.filter((r) => r.verdict === 'differs').length,
        failed: own.filter((r) => !['identical', 'differs'].includes(r.verdict)).length,
      };
    }),
  );
  writeTable('roundtrip_summary', summary, [
    { key: 'source', header: 'DDL source' },
    { key: 'dialect', header: 'Dialect' },
    { key: 'cases', header: 'Cases', align: 'r' },
    { key: 'identical', header: 'Identical catalog', align: 'r' },
    { key: 'differs', header: 'Catalog differs', align: 'r' },
    { key: 'failed', header: 'Failed to round-trip', align: 'r' },
  ]);

  const constructs = [...new Set(diffs.map((d) => d.construct))].sort();
  const lossRows = constructs.map((construct) => {
    const own = diffs.filter((d) => d.construct === construct);
    return {
      construct,
      occurrences: own.length,
      generated_inputs: own.filter((d) => d.source === 'generated').length,
      hand_written_inputs: own.filter((d) => d.source === 'hand-written').length,
      example: `${own[0].id} (${own[0].dialect}): ${own[0].detail}`,
    };
  });
  writeTable('roundtrip_information_loss', lossRows.length ? lossRows : [{ construct: '(none)', occurrences: 0, generated_inputs: 0, hand_written_inputs: 0, example: '' }], [
    { key: 'construct', header: 'Construct that changed' },
    { key: 'occurrences', header: 'Occurrences', align: 'r' },
    { key: 'generated_inputs', header: 'In generated DDL', align: 'r' },
    { key: 'hand_written_inputs', header: 'In hand-written DDL', align: 'r' },
    { key: 'example', header: 'Example' },
  ]);
  const inventoryRows = Object.entries(inventory).map(([construct, instances]) => {
    const changed = diffs.filter((d) => d.construct === construct).length;
    return { construct, instances, changed_or_lost: changed, preserved: instances ? `${(((instances - changed) / instances) * 100).toFixed(1)}%` : 'n/a' };
  });
  writeTable('roundtrip_inventory', inventoryRows, [
    { key: 'construct', header: 'Relational construct' },
    { key: 'instances', header: 'Instances in input DDL', align: 'r' },
    { key: 'changed_or_lost', header: 'Changed or lost', align: 'r' },
    { key: 'preserved', header: 'Preserved', align: 'r' },
  ]);
  // Conceptual recovery: what the importer reconstructs from the (PostgreSQL) DDL that the tool generated for each model.
  const original = {};
  const recovered = {};
  for (const m of manifest.models) {
    const model = loadModel(m.file);
    const back = parseSQLToModel(generate(toIR(model), 'postgres'));
    for (const [name, value] of Object.entries(conceptualFeatures(model))) original[name] = (original[name] || 0) + value;
    for (const [name, value] of Object.entries(conceptualFeatures(back))) recovered[name] = (recovered[name] || 0) + value;
  }
  const conceptualRows = Object.keys(original).map((construct) => ({
    construct,
    in_corpus_models: original[construct],
    in_recovered_models: recovered[construct],
    outcome: original[construct] === 0 && recovered[construct] === 0 ? 'not exercised' : recovered[construct] === original[construct] ? 'same count' : recovered[construct] === 0 ? 'not recovered' : recovered[construct] > original[construct] ? 'over-reported (constructs inferred that the model did not have)' : 'under-reported',
  }));
  writeTable('roundtrip_conceptual_recovery', conceptualRows, [
    { key: 'construct', header: 'Conceptual construct' },
    { key: 'in_corpus_models', header: 'In the 14 corpus models', align: 'r' },
    { key: 'in_recovered_models', header: 'In the models recovered from their DDL', align: 'r' },
    { key: 'outcome', header: 'Outcome' },
  ]);
  const unrecoverable = Object.entries(featureTotals).map(([feature, t]) => ({
    feature,
    in_inputs: t.input,
    in_regenerated: t.output,
    outcome: t.input === 0 ? 'not exercised' : t.output === 0 ? 'dropped' : t.output === t.input ? 'kept' : t.output > t.input ? 'added or rewritten by the exporter' : 'partly dropped',
  }));
  writeTable('roundtrip_not_recovered', unrecoverable, [
    { key: 'feature', header: 'SQL feature outside the conceptual model' },
    { key: 'in_inputs', header: 'In input DDL', align: 'r' },
    { key: 'in_regenerated', header: 'In regenerated DDL', align: 'r' },
    { key: 'outcome', header: 'Outcome' },
  ]);
  writeLog('roundtrip_differences.tsv', ['source\tinput\tdialect\tconstruct\tdetail', ...diffs.map((d) => `${d.source}\t${d.id}\t${d.dialect}\t${d.construct}\t${d.detail}`)].join('\n'));
  log(`roundtrip: ${rows.length} cases, ${diffs.length} differences`);
  return { rows, summary, lossRows, unrecoverable };
}
